, chamou_google: $('Calcular folga e próxima checagem').item.json.chamou_google, routing: $('Calcular folga e próxima checagem').item.json.routing })] }}"}},"id":"bacc80bf-e23c-5dd6-9e4a-5b765b2859b8","name":"Gravar evento","type":"n8n-nodes-base.postgres","typeVersion":2.5,"position":[2160,300]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO audit.evento_integracao (correlation_id, workflow, evento, payload) VALUES ($1,$2,$3,$4::jsonb)","options":{"queryReplacement":"={{ [$('Validar check-in').item.json.correlation_id, '12_trajeto_medico', 'trajeto_' + $('Validar check-in').item.json.evento, JSON.stringify({ janela: $('Validar check-in').item.json.janela, unidade: $('Validar check-in').item.json.unidade })] }}"}},"id":"7ec547a8-9b7a-5385-9f58-3bdd4848529e","name":"Gravar abertura/fechamento","type":"n8n-nodes-base.postgres","typeVersion":2.5,"position":[720,-260]},{"parameters":{"content":"Intervalo adaptativo: tique de 1 min, mas cada trajeto só é recalculado quando vence a próxima checagem (5 min com folga, 1 min com folga < 15 min). Acima de 30 min de folga usa TRAFFIC_UNAWARE (SKU Essentials). GPS parado (< 200 m) reaproveita o ETA. Posição bruta só no Redis, com TTL de 6 h. Até 3 trajetos por dia (ida, retorno do almoço e 2º local). Variáveis: GOOGLE_MAPS_API_KEY, N8N_BASE_URL.","height":200,"width":440},"id":"1c9707c4-20e6-584e-ad71-b8331a9d2d4e","name":"Nota","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[700,-520]}],"connections":{"Check-in de saída ou chegada (app do médico)":{"main":[[{"node":"Validar check-in","type":"main","index":0}]]},"Validar check-in":{"main":[[{"node":"Abrir ou fechar trajeto","type":"main","index":0}]]},"Abrir ou fechar trajeto":{"main":[[{"node":"Gravar abertura/fechamento","type":"main","index":0}]]},"Ping GPS (app do médico)":{"main":[[{"node":"Guardar posição no Redis (TTL 6 h)","type":"main","index":0}]]},"A cada 1 min":{"main":[[{"node":"Trajetos com checagem vencida","type":"main","index":0}]]},"Trajetos com checagem vencida":{"main":[[{"node":"Última posição (Redis)","type":"main","index":0}]]},"Última posição (Redis)":{"main":[[{"node":"Decidir chamada","type":"main","index":0}]]},"Decidir chamada":{"main":[[{"node":"Chamar o Google agora?","type":"main","index":0}]]},"Chamar o Google agora?":{"main":[[{"node":"Google Routes · computeRoutes","type":"main","index":0}],[{"node":"Calcular folga e próxima checagem","type":"main","index":0}]]},"Google Routes · computeRoutes":{"main":[[{"node":"Calcular folga e próxima checagem","type":"main","index":0}]]},"Calcular folga e próxima checagem":{"main":[[{"node":"Atualizar trajeto","type":"main","index":0}]]},"Atualizar trajeto":{"main":[[{"node":"Estado mudou?","type":"main","index":0}]]},"Estado mudou?":{"main":[[{"node":"Incidente?","type":"main","index":0},{"node":"Gravar evento","type":"main","index":0}],[]]},"Incidente?":{"main":[[{"node":"Acionar cobertura (14)","type":"main","index":0}],[{"node":"Avisar central e recepção","type":"main","index":0},{"node":"Informar a fila digital (13)","type":"main","index":0}]]}},"active":false,"settings":{"executionOrder":"v1"},"tags":[{"name":"DaisyCare"},{"name":"modelo-ouro"}],"meta":{"descricao":"Abre até 3 trajetos por dia por médico, calcula o ETA no Google Routes com intervalo adaptativo e avisa central, fila digital (13) ou cobertura (14) só quando o estado muda.","aviso":"Simulação. Vincule as credenciais (PostgreSQL, Redis) e defina as variáveis indicadas antes de ativar. Sem CPF nem dados clínicos."}}},{"file":"daisycare_13_fila_digital.json","name":"13 · Fila digital e controle dos atendimentos (tempo previsto e avisos)","json":{"name":"13 · Fila digital e controle dos atendimentos (tempo previsto e avisos)","nodes":[{"parameters":{"httpMethod":"POST","path":"daisy-atendimento","responseMode":"onReceived","options":{}},"id":"66651377-152b-54e0-97e0-effd5c4f3602","name":"Evento de atendimento","type":"n8n-nodes-base.webhook","typeVersion":2,"position":[0,0],"webhookId":"46e0da97-31f4-5a7f-a3d6-d810ffe51981"},{"parameters":{"httpMethod":"POST","path":"daisy-fila-eta","responseMode":"onReceived","options":{}},"id":"7e1b6a69-fb80-53c1-a66e-3b7dfdc6c057","name":"ETA do médico (12)","type":"n8n-nodes-base.webhook","typeVersion":2,"position":[0,200],"webhookId":"61a46b77-03cd-5a8c-9366-6be58079b918"},{"parameters":{"mode":"runOnceForEachItem","jsCode":"// Normaliza os dois tipos de entrada: evento de atendimento ou ETA do médico (12).
const b = $json.body || {};
const tipos = ['checkin_paciente', 'inicio', 'fim', 'eta_medico'];
const tipo = b.tipo || (b.atraso_chegada_min != null ? 'eta_medico' : null);
if (!b.medico_id || !tipos.includes(tipo)) throw new Error('payload inválido');
return { json: { medico_id: String(b.medico_id), especialidade: b.especialidade || null, tipo,
  paciente_token: b.paciente_token || null, duracao_min: b.duracao_min ?? null,
  atraso_chegada_min: b.atraso_chegada_min ?? null,
  correlation_id: b.correlation_id || ('FILA-' + b.medico_id + '-' + Date.now().toString(36)) } };"},"id":"a665bfc6-f25b-5336-9145-b05eb7f5dd67","name":"Normalizar evento","type":"n8n-nodes-base.code","typeVersion":2,"position":[240,100]},{"parameters":{"operation":"get","propertyName":"fila_raw","key":"=fila:{{ $json.medico_id }}","keyType":"string","options":{}},"id":"ba4e00b5-dbd4-5e2a-b2c8-926d615e5806","name":"Fila do médico (Redis)","type":"n8n-nodes-base.redis","typeVersion":1,"position":[480,100]},{"parameters":{"operation":"executeQuery","query":"SELECT (SELECT sla_min FROM ops.sla_especialidade WHERE especialidade = $2) AS sla_min, percentile_cont(0.5) WITHIN GROUP (ORDER BY duracao_min) AS mediana_min, count(*) AS n FROM (SELECT duracao_min FROM ops.consulta WHERE medico_id = $1 AND especialidade = $2 AND duracao_min IS NOT NULL ORDER BY fim_em DESC LIMIT 20) u","options":{"queryReplacement":"={{ [$json.medico_id, $json.especialidade] }}"}},"id":"3be92ad6-1537-5f18-a4cb-42f70cb7442a","name":"Mediana das últimas 20 consultas","type":"n8n-nodes-base.postgres","typeVersion":2.5,"position":[720,100],"alwaysOutputData":true},{"parameters":{"mode":"runOnceForEachItem","jsCode":"// Atualiza a fila do médico e prevê a espera de cada paciente.
const ev = $('Normalizar evento').item.json;
const raw = $('Fila do médico (Redis)').item.json.fila_raw;
const est = $json;                                    // mediana das últimas 20 consultas + SLA
const fila = raw ? JSON.parse(raw) : { pacientes: [], atual: null, atraso_chegada_min: 0, atraso_acumulado_min: 0 };
const agora = Date.now();
let fim = false, duracao = null;

if (ev.tipo === 'eta_medico') fila.atraso_chegada_min = Math.max(0, ev.atraso_chegada_min || 0);
if (ev.tipo === 'checkin_paciente' && ev.paciente_token && !fila.pacientes.some(p => p.token === ev.paciente_token))
  fila.pacientes.push({ token: ev.paciente_token, checkin_em: new Date().toISOString(), ultimo_aviso_min: null });
if (ev.tipo === 'inicio') {
  fila.pacientes = fila.pacientes.filter(p => p.token !== ev.paciente_token);
  fila.atual = { token: ev.paciente_token, inicio_em: new Date().toISOString() };
  fila.atraso_chegada_min = 0;                          // médico já está atendendo
}
if (ev.tipo === 'fim' && fila.atual) {
  duracao = ev.duracao_min ?? Math.round((agora - new Date(fila.atual.inicio_em)) / 60000);
  fila.atraso_acumulado_min = Math.max(0, (fila.atraso_acumulado_min || 0) + duracao - (est.sla_min || duracao));
  fila.atual = null; fim = true;
}

// tempo típico: mediana do próprio médico com pelo menos 5 consultas; senão o SLA da especialidade
const tipico = est.n >= 5 && est.mediana_min ? Number(est.mediana_min) : Number(est.sla_min || 20);
const restanteAtual = fila.atual ? Math.max(0, tipico - (agora - new Date(fila.atual.inicio_em)) / 60000) : 0;
const avisos = [];
fila.pacientes.forEach((p, i) => {
  const espera = Math.round(restanteAtual + i * tipico + (fila.atraso_chegada_min || 0));
  const motivo = p.ultimo_aviso_min == null ? 'checkin'
    : (i === 0 && !p.avisado_proximo) ? 'proximo'
    : Math.abs(espera - p.ultimo_aviso_min) > 10 ? 'mudou_mais_de_10_min' : null;
  if (motivo) {
    avisos.push({ paciente_token: p.token, posicao: i + 1, espera_min: espera, motivo });
    p.ultimo_aviso_min = espera; if (i === 0) p.avisado_proximo = true;
  }
});
return { json: {
  correlation_id: ev.correlation_id, medico_id: ev.medico_id, especialidade: ev.especialidade, tipo: ev.tipo,
  fila_json: JSON.stringify(fila), na_fila: fila.pacientes.length, tempo_tipico_min: tipico,
  atraso_acumulado_min: fila.atraso_acumulado_min || 0, fim, duracao_min: duracao,
  paciente_token: ev.paciente_token, avisos
} };"},"id":"db5d10ce-1e05-57a1-b61e-7c5f7d76e453","name":"Atualizar fila e prever espera","type":"n8n-nodes-base.code","typeVersion":2,"position":[960,100]},{"parameters":{"operation":"set","key":"=fila:{{ $json.medico_id }}","value":"={{ $json.fila_json }}","keyType":"string","expire":true,"ttl":57600},"id":"0db09604-7488-5937-9ede-4458002d52b5","name":"Salvar fila (Redis, TTL 16 h)","type":"n8n-nodes-base.redis","typeVersion":1,"position":[1200,100]},{"parameters":{"jsCode":"// Um item por aviso; sem avisos, nada segue.
