,"url":"={{ $env.N8N_BASE_URL }}/webhook/daisy-cobertura","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ correlation_id: $('Atualizar fila e prever espera').item.json.correlation_id, medico_id: $('Atualizar fila e prever espera').item.json.medico_id, especialidade: $('Atualizar fila e prever espera').item.json.especialidade, motivo: 'atraso_acumulado' }) }}","options":{}},"id":"efaa3e83-b46e-5973-8738-6ff3eb172564","name":"Pedir cobertura (14)","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1680,240]},{"parameters":{"conditions":{"number":[{"value1":"={{ $('Atualizar fila e prever espera').item.json.atraso_acumulado_min }}","operation":"larger","value2":20}]}},"id":"893547a5-a02e-5fea-b5e6-9aa1642908c3","name":"Atraso > 20 min?","type":"n8n-nodes-base.if","typeVersion":1,"position":[1680,400]},{"parameters":{"method":"POST","url":"={{ $env.N8N_BASE_URL }}/webhook/daisy-agenda-reorganizar","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ correlation_id: $('Atualizar fila e prever espera').item.json.correlation_id, medico_id: $('Atualizar fila e prever espera').item.json.medico_id, atraso_min: $('Atualizar fila e prever espera').item.json.atraso_acumulado_min }) }}","options":{}},"id":"b5dd9911-a0de-53ed-8a37-c303ea71e9e7","name":"Reorganizar agenda (11)","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1920,400]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO audit.evento_integracao (correlation_id, workflow, evento, payload) VALUES ($1,$2,$3,$4::jsonb)","options":{"queryReplacement":"={{ [$('Atualizar fila e prever espera').item.json.correlation_id, '13_fila_digital', $('Atualizar fila e prever espera').item.json.fim ? 'consulta_finalizada' : 'fila_' + $('Atualizar fila e prever espera').item.json.tipo, JSON.stringify({ medico_id: $('Atualizar fila e prever espera').item.json.medico_id, na_fila: $('Atualizar fila e prever espera').item.json.na_fila, tempo_tipico_min: $('Atualizar fila e prever espera').item.json.tempo_tipico_min, duracao_min: $('Atualizar fila e prever espera').item.json.duracao_min, atraso_acumulado_min: $('Atualizar fila e prever espera').item.json.atraso_acumulado_min, avisos: ($('Atualizar fila e prever espera').item.json.avisos || []).length })] }}"}},"id":"623c097e-eb8e-5d85-ba63-033ba6c21aa3","name":"Gravar evento","type":"n8n-nodes-base.postgres","typeVersion":2.5,"position":[1440,520]},{"parameters":{"content":"Espera prevista = restante da consulta atual + (posição − 1) × tempo típico + atraso de chegada do médico (12). Tempo típico = mediana das últimas 20 consultas do médico (mín. 5); senão, SLA da especialidade. A Daisy avisa no check-in, quando o paciente vira o próximo e quando a previsão muda mais de 10 min. Fila no Redis; só os eventos vão ao PostgreSQL.","height":190,"width":440},"id":"cb75e8fa-4c4f-58b3-9062-944e841886e7","name":"Nota","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[900,-260]}],"connections":{"Evento de atendimento":{"main":[[{"node":"Normalizar evento","type":"main","index":0}]]},"ETA do médico (12)":{"main":[[{"node":"Normalizar evento","type":"main","index":0}]]},"Normalizar evento":{"main":[[{"node":"Fila do médico (Redis)","type":"main","index":0}]]},"Fila do médico (Redis)":{"main":[[{"node":"Mediana das últimas 20 consultas","type":"main","index":0}]]},"Mediana das últimas 20 consultas":{"main":[[{"node":"Atualizar fila e prever espera","type":"main","index":0}]]},"Atualizar fila e prever espera":{"main":[[{"node":"Salvar fila (Redis, TTL 16 h)","type":"main","index":0}]]},"Salvar fila (Redis, TTL 16 h)":{"main":[[{"node":"Separar avisos","type":"main","index":0},{"node":"Fim da consulta?","type":"main","index":0},{"node":"Atraso > 30 min?","type":"main","index":0},{"node":"Gravar evento","type":"main","index":0}]]},"Separar avisos":{"main":[[{"node":"Daisy avisa o paciente (10)","type":"main","index":0}]]},"Fim da consulta?":{"main":[[{"node":"Disparar NPS (